from typing import Literal

from pydantic import BaseModel, Field

from app.models.qa import Citation


class AnswerDraft(BaseModel):
    """Structured output generated by the LLM."""

    can_answer: bool = Field(description="Whether the evidence supports an answer.")

    answer: str = Field(description="Answer using only the provided evidence.")

    evidence_ids: list[int] = Field(
        description="IDs of the evidence supporting the answer."
    )


class AnswerResult(BaseModel):
    """Validated result returned to the Agent Graph."""

    answer: str
    citations: list[Citation]

    status: Literal[
        "answered",
        "insufficient_evidence",
        "invalid_citations",
    ]
